@spec view_context_spec  src=tests/specs/view_context_spec.lua  loc=640  cases=39
@exercises tuning (tuning), trackerView (h.vm), configManager (h.cm)
@surface   tuning.genRank2, tuning.derive, tuning.stepToMidi, vm:activeTemper, cm:set
@harness   mk{seed.ccs}

# Intent
  Pins the projection contract of newViewContext directly, without
  going through vm. The context is built by hand from synthetic args so
  failures localise to newViewContext rather than to vm:rebuild's wiring.
  vm-integration tests live in vm_grid_spec.

# Helpers
  @fn logicalGrid()  @ 13-17
      -- Uniform logical grid for 240 ppq/QN, 4 rows/beat, length 3840 ppq.
  @fn meantone12()  @ 21-25
      -- Quarter-comma meantone's twelve-note MOS (Eb..G#, C at the unison): an
      -- unequal scale, so a step's two neighbours sit at different distances.
  @fn mkCtx(overrides)  @ 27-39
  @fn mkCtxRpb(rpb, ppqPerQN)  @ 45-56
      -- Non-divisor rpb: ppqPerRow is fractional, so row · ppqPerRow lands
      -- between integers for most rows. Pins that rowToPPQ / ppqToRow are
      -- now both float — the old F4 asymmetry (rowToPPQ rounded at the
      -- realisation boundary) is gone; "on the grid" is owned by isOnGrid.
  @fn threeCallForm(ctx, ppq, chan)  @ 62-67
      -- The three-call form ctx:placeRow replaces: ppqToRow (the tail's start
      -- row), trackerView's ppqRowOf (snap when on-grid, else floor) and
      -- isOnGrid. Recomposed here so the cases compare definitions rather
      -- than hard-coded numbers.
  @fn eqThreeCallForm(ctx, ppq, label)  @ 69-75

# Cases
  @case 'identity swing: ppqToRow / rowToPPQ round-trip on grid-aligned rows'  [pure]  @ 81-88
  @case 'identity swing: ppqToRow and rowToPPQ are exact inverses, both returning float'  [pure]  @ 92-100
  @case 'snapRow snaps fractional ppq to the nearest row'  [pure]  @ 104-113
  @case 'ppq above length saturates at numRows; ppq below 0 saturates at 0'  [pure]  @ 117-124
  @case 'snapRow(rowToPPQ(r,c),c) == r under non-divisor rpb'  [pure]  @ 134-143
  @case 'on-grid p round-trips exactly under non-divisor rpb'  [pure]  @ 147-157
  @case 'ppqToRow ∘ rowToPPQ is the identity (float) under non-divisor rpb'  [pure]  @ 161-174
  @case 'isOnGrid: exact row ppqs are on-grid'  [pure]  @ 180-187
  @case 'isOnGrid: tolerates float drift up to (but not including) 0.5 ppq'  [pure]  @ 191-202
  @case 'isOnGrid: rebuild-inverted ppqs land on-grid under non-divisor rpb'  [pure]  @ 206-217
  @case 'placeRow agrees with the three-call form on grid, drift, off-grid and both clamps'  [pure]  @ 223-238
  @case 'placeRow: the three views are the row, its cell row and the on-grid verdict'  [pure]  @ 242-256
  @case 'placeRow agrees with the three-call form under non-divisor rpb'  [pure]  @ 260-271
  @case 'ppqPerRow exposes the rebuild frame logical ppq width'  [pure]  @ 277-280
  @case 'activeTemper is nil when no temperament is bound'  [pure]  @ 286-289
  @case 'activeTemper returns the bound temperament object'  [pure]  @ 293-297
  @case 'both temperament lenses return nil when no temperament is bound'  [pure]  @ 301-305
  @case 'noteLabel under 12EDO: pitch 60 spells C-4'  [pure]  @ 309-314
  @case 'noteDeviation under 12EDO: an undetuned pitch 60 sits on its step'  [pure]  @ 318-322
  @case 'noteLabel reports a negative octave alongside its magnitude'  [pure]  @ 326-333
  @case 'noteDeviation signed gap: positive detune yields positive gap (sharp)'  [pure]  @ 337-344
  @case 'noteDeviation: sub-epsilon detune offset reads on-temper (gap clamped)'  [pure]  @ 348-359
  @case 'noteDeviation reports cents alone, with no window half beside them'  [pure]  @ 363-374
  @case 'noteLabel names the step the intent carries, not the one its sound snaps to'  [pure]  @ 380-385
  @case 'noteDeviation measures from the intent, past the half-window that once bound it'  [pure]  @ 391-398
  @case 'rowBeatInfo at row 0 under 4/4 reports (bar, beat) = (true, true)'  [pure]  @ 404-409
  @case 'rowBeatInfo at beat boundary: only beat flag set'  [pure]  @ 413-419
  @case 'rowBeatInfo at bar boundary: both flags set'  [pure]  @ 423-428
  @case 'rowBeatInfo at non-boundary row: both flags clear'  [pure]  @ 432-437
  @case 'rowBeatInfo respects mid-take time-sig change'  [pure]  @ 441-456
  @case 'barBeatSub at row 0 returns (1, 1, 1, ts)'  [pure]  @ 460-465
  @case 'barBeatSub mid-bar: (bar, beat, sub) walks the row index'  [pure]  @ 469-474
  @case 'barBeatSub crosses a time-sig change and resumes counting'  [pure]  @ 478-495
  @case 'ghosts: linear pair populates interior rows with proportional vals'  [harness]  @ 511-531
  @case 'ghosts: entries carry fromEvt and toEvt references'  [harness]  @ 535-554
  @case 'ghosts: step shape produces no ghosts'  [harness]  @ 558-573
  @case 'ghosts: single event yields no ghosts'  [harness]  @ 577-591
  @case 'ghosts: non-linear shape routes through tm:interpolate'  [harness]  @ 595-612
  @case 'temper resolves via cfg.tempers, falls back to built-in presets, returns nil for unknown names'  [harness]  @ 616-638

